-- create-table /RT/PACKAGES
CREATE TABLE "/RT/PACKAGES" (
  "PACKAGE_ID" VARCHAR(16) NOT NULL,
  "VERSION" VARCHAR(64) NOT NULL,
  "DESCRIPTION" TEXT,
  "INSTALLED_AT" TIMESTAMPTZ NOT NULL,
  "UPDATED_AT" TIMESTAMPTZ NOT NULL,
  "LANGUAGE_VERSION" INTEGER,
  CONSTRAINT "/RT/PACKAGES#PK" PRIMARY KEY ("PACKAGE_ID")
);

-- create-table /RT/ARRAY_TYPES
CREATE TABLE "/RT/ARRAY_TYPES" (
  "ARRAY_TYPE" VARCHAR(63) NOT NULL,
  "PACKAGE_ID" VARCHAR(16) NOT NULL,
  "ROW_KIND" VARCHAR(12) NOT NULL,
  "ROW_TYPE" VARCHAR(63) NOT NULL,
  "KEY_UNIQUE" BOOLEAN,
  CONSTRAINT "/RT/ARRAY_TYPES#PK" PRIMARY KEY ("ARRAY_TYPE"),
  CONSTRAINT "/RT/ARRAY_TYPES#FK#PACKAGE" FOREIGN KEY ("PACKAGE_ID") REFERENCES "/RT/PACKAGES" ("PACKAGE_ID") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/ARRAY_TYPES#CK#ROW_KIND" CHECK ("ROW_KIND" IN ('DATA_ELEMENT', 'DOMAIN', 'STRUCTURE', 'ARRAY_TYPE'))
);

-- create-table /RT/ARRAY_TYPE_KEYS
CREATE TABLE "/RT/ARRAY_TYPE_KEYS" (
  "ARRAY_TYPE" VARCHAR(63) NOT NULL,
  "POSITION" INTEGER NOT NULL,
  "FIELD_NAME" VARCHAR(63) NOT NULL,
  CONSTRAINT "/RT/ARRAY_TYPE_KEYS#PK" PRIMARY KEY ("ARRAY_TYPE", "POSITION"),
  CONSTRAINT "/RT/ARRAY_TYPE_KEYS#FK#ARRAY_TYPE" FOREIGN KEY ("ARRAY_TYPE") REFERENCES "/RT/ARRAY_TYPES" ("ARRAY_TYPE") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /RT/LANGUAGES
CREATE TABLE "/RT/LANGUAGES" (
  "LANGUAGE" VARCHAR(2) NOT NULL,
  "NAME" VARCHAR(60) NOT NULL,
  CONSTRAINT "/RT/LANGUAGES#PK" PRIMARY KEY ("LANGUAGE")
);

-- create-table /RT/ARRAY_TYPE_TEXTS
CREATE TABLE "/RT/ARRAY_TYPE_TEXTS" (
  "ARRAY_TYPE" VARCHAR(63) NOT NULL,
  "LANGUAGE" VARCHAR(2) NOT NULL,
  "LABEL" VARCHAR(60) NOT NULL,
  "DESCRIPTION" TEXT,
  CONSTRAINT "/RT/ARRAY_TYPE_TEXTS#PK" PRIMARY KEY ("ARRAY_TYPE", "LANGUAGE"),
  CONSTRAINT "/RT/ARRAY_TYPE_TEXTS#FK#ARRAY_TYPE" FOREIGN KEY ("ARRAY_TYPE") REFERENCES "/RT/ARRAY_TYPES" ("ARRAY_TYPE") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/ARRAY_TYPE_TEXTS#FK#LANGUAGE" FOREIGN KEY ("LANGUAGE") REFERENCES "/RT/LANGUAGES" ("LANGUAGE") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /RT/ASSET_BLOBS
CREATE TABLE "/RT/ASSET_BLOBS" (
  "SHA256" VARCHAR(64) NOT NULL,
  "SIZE" BIGINT NOT NULL,
  "CHUNKS" INTEGER NOT NULL,
  CONSTRAINT "/RT/ASSET_BLOBS#PK" PRIMARY KEY ("SHA256")
);

-- create-table /RT/ASSET_CHUNKS
CREATE TABLE "/RT/ASSET_CHUNKS" (
  "SHA256" VARCHAR(64) NOT NULL,
  "SEQ" INTEGER NOT NULL,
  "DATA" BYTEA NOT NULL,
  CONSTRAINT "/RT/ASSET_CHUNKS#PK" PRIMARY KEY ("SHA256", "SEQ"),
  CONSTRAINT "/RT/ASSET_CHUNKS#FK#BLOB" FOREIGN KEY ("SHA256") REFERENCES "/RT/ASSET_BLOBS" ("SHA256") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /RT/ASSET_REPOSITORIES
CREATE TABLE "/RT/ASSET_REPOSITORIES" (
  "PACKAGE_ID" VARCHAR(16) NOT NULL,
  "REPOSITORY_ID" VARCHAR(32) NOT NULL,
  CONSTRAINT "/RT/ASSET_REPOSITORIES#PK" PRIMARY KEY ("PACKAGE_ID", "REPOSITORY_ID"),
  CONSTRAINT "/RT/ASSET_REPOSITORIES#FK#PACKAGE" FOREIGN KEY ("PACKAGE_ID") REFERENCES "/RT/PACKAGES" ("PACKAGE_ID") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /RT/ASSET_ENTRIES
CREATE TABLE "/RT/ASSET_ENTRIES" (
  "PACKAGE_ID" VARCHAR(16) NOT NULL,
  "REPOSITORY_ID" VARCHAR(32) NOT NULL,
  "PATH" VARCHAR(255) NOT NULL,
  "KIND" VARCHAR(6) NOT NULL,
  "PARENT_PATH" VARCHAR(255),
  "MIME_TYPE" VARCHAR(127),
  "SHA256" VARCHAR(64),
  "SIZE" BIGINT,
  "SOURCE_PATH" VARCHAR(255),
  "MODIFIED_AT" TIMESTAMPTZ,
  CONSTRAINT "/RT/ASSET_ENTRIES#PK" PRIMARY KEY ("PACKAGE_ID", "REPOSITORY_ID", "PATH"),
  CONSTRAINT "/RT/ASSET_ENTRIES#FK#REPOSITORY" FOREIGN KEY ("PACKAGE_ID", "REPOSITORY_ID") REFERENCES "/RT/ASSET_REPOSITORIES" ("PACKAGE_ID", "REPOSITORY_ID") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/ASSET_ENTRIES#FK#PARENT" FOREIGN KEY ("PACKAGE_ID", "REPOSITORY_ID", "PARENT_PATH") REFERENCES "/RT/ASSET_ENTRIES" ("PACKAGE_ID", "REPOSITORY_ID", "PATH") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/ASSET_ENTRIES#FK#BLOB" FOREIGN KEY ("SHA256") REFERENCES "/RT/ASSET_BLOBS" ("SHA256") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/ASSET_ENTRIES#CK#KIND" CHECK ("KIND" IN ('FOLDER', 'FILE'))
);

-- create-table /RT/ASSET_ENTRY_TEXTS
CREATE TABLE "/RT/ASSET_ENTRY_TEXTS" (
  "PACKAGE_ID" VARCHAR(16) NOT NULL,
  "REPOSITORY_ID" VARCHAR(32) NOT NULL,
  "PATH" VARCHAR(255) NOT NULL,
  "LANGUAGE" VARCHAR(2) NOT NULL,
  "DESCRIPTION" TEXT NOT NULL,
  CONSTRAINT "/RT/ASSET_ENTRY_TEXTS#PK" PRIMARY KEY ("PACKAGE_ID", "REPOSITORY_ID", "PATH", "LANGUAGE"),
  CONSTRAINT "/RT/ASSET_ENTRY_TEXTS#FK#ENTRY" FOREIGN KEY ("PACKAGE_ID", "REPOSITORY_ID", "PATH") REFERENCES "/RT/ASSET_ENTRIES" ("PACKAGE_ID", "REPOSITORY_ID", "PATH") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/ASSET_ENTRY_TEXTS#FK#LANGUAGE" FOREIGN KEY ("LANGUAGE") REFERENCES "/RT/LANGUAGES" ("LANGUAGE") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /RT/ASSET_REPOSITORY_TEXTS
CREATE TABLE "/RT/ASSET_REPOSITORY_TEXTS" (
  "PACKAGE_ID" VARCHAR(16) NOT NULL,
  "REPOSITORY_ID" VARCHAR(32) NOT NULL,
  "LANGUAGE" VARCHAR(2) NOT NULL,
  "DESCRIPTION" TEXT NOT NULL,
  CONSTRAINT "/RT/ASSET_REPOSITORY_TEXTS#PK" PRIMARY KEY ("PACKAGE_ID", "REPOSITORY_ID", "LANGUAGE"),
  CONSTRAINT "/RT/ASSET_REPOSITORY_TEXTS#FK#REPOSITORY" FOREIGN KEY ("PACKAGE_ID", "REPOSITORY_ID") REFERENCES "/RT/ASSET_REPOSITORIES" ("PACKAGE_ID", "REPOSITORY_ID") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/ASSET_REPOSITORY_TEXTS#FK#LANGUAGE" FOREIGN KEY ("LANGUAGE") REFERENCES "/RT/LANGUAGES" ("LANGUAGE") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /RT/ASSET_VARIANTS
CREATE TABLE "/RT/ASSET_VARIANTS" (
  "PACKAGE_ID" VARCHAR(16) NOT NULL,
  "REPOSITORY_ID" VARCHAR(32) NOT NULL,
  "PATH" VARCHAR(255) NOT NULL,
  "LANGUAGE" VARCHAR(2) NOT NULL,
  "SOURCE_PATH" VARCHAR(255) NOT NULL,
  "SHA256" VARCHAR(64) NOT NULL,
  "SIZE" BIGINT NOT NULL,
  "MODIFIED_AT" TIMESTAMPTZ NOT NULL,
  CONSTRAINT "/RT/ASSET_VARIANTS#PK" PRIMARY KEY ("PACKAGE_ID", "REPOSITORY_ID", "PATH", "LANGUAGE"),
  CONSTRAINT "/RT/ASSET_VARIANTS#FK#ENTRY" FOREIGN KEY ("PACKAGE_ID", "REPOSITORY_ID", "PATH") REFERENCES "/RT/ASSET_ENTRIES" ("PACKAGE_ID", "REPOSITORY_ID", "PATH") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/ASSET_VARIANTS#FK#LANGUAGE" FOREIGN KEY ("LANGUAGE") REFERENCES "/RT/LANGUAGES" ("LANGUAGE") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/ASSET_VARIANTS#FK#BLOB" FOREIGN KEY ("SHA256") REFERENCES "/RT/ASSET_BLOBS" ("SHA256") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /RT/BYTECODE
CREATE TABLE "/RT/BYTECODE" (
  "PACKAGE_ID" VARCHAR(16) NOT NULL,
  "FORMAT_VERSION" INTEGER NOT NULL,
  "LANGUAGE_VERSION" INTEGER NOT NULL,
  "CODE" BYTEA NOT NULL,
  "SHA256" VARCHAR(64) NOT NULL,
  "GENERATION" BIGINT NOT NULL,
  "COMPILED_AT" TIMESTAMPTZ NOT NULL,
  CONSTRAINT "/RT/BYTECODE#PK" PRIMARY KEY ("PACKAGE_ID"),
  CONSTRAINT "/RT/BYTECODE#FK#PACKAGE" FOREIGN KEY ("PACKAGE_ID") REFERENCES "/RT/PACKAGES" ("PACKAGE_ID") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /RT/CODE_GENERATION
CREATE TABLE "/RT/CODE_GENERATION" (
  "ID" INTEGER NOT NULL,
  "GENERATION" BIGINT NOT NULL,
  "CHANGED_AT" TIMESTAMPTZ NOT NULL,
  CONSTRAINT "/RT/CODE_GENERATION#PK" PRIMARY KEY ("ID")
);

-- create-table /RT/CODE_INCLUDES
CREATE TABLE "/RT/CODE_INCLUDES" (
  "PACKAGE_ID" VARCHAR(16) NOT NULL,
  "INCLUDE_NAME" VARCHAR(63) NOT NULL,
  "INCLUDE_PACKAGE" VARCHAR(16) NOT NULL,
  "IF_FOUND" BOOLEAN NOT NULL,
  "FOUND" BOOLEAN NOT NULL,
  CONSTRAINT "/RT/CODE_INCLUDES#PK" PRIMARY KEY ("PACKAGE_ID", "INCLUDE_NAME"),
  CONSTRAINT "/RT/CODE_INCLUDES#FK#PACKAGE" FOREIGN KEY ("PACKAGE_ID") REFERENCES "/RT/PACKAGES" ("PACKAGE_ID") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /RT/CODE_USES
CREATE TABLE "/RT/CODE_USES" (
  "PACKAGE_ID" VARCHAR(16) NOT NULL,
  "POSITION" INTEGER NOT NULL,
  "FILE_PATH" VARCHAR(255) NOT NULL,
  "LINE_NO" INTEGER NOT NULL,
  "COLUMN_NO" INTEGER NOT NULL,
  "OBJECT_KIND" VARCHAR(16) NOT NULL,
  "OBJECT_NAME" VARCHAR(63) NOT NULL,
  "MEMBER_NAME" VARCHAR(63),
  "OBJECT_PACKAGE" VARCHAR(16),
  CONSTRAINT "/RT/CODE_USES#PK" PRIMARY KEY ("PACKAGE_ID", "POSITION"),
  CONSTRAINT "/RT/CODE_USES#FK#PACKAGE" FOREIGN KEY ("PACKAGE_ID") REFERENCES "/RT/PACKAGES" ("PACKAGE_ID") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/CODE_USES#CK#OBJECT_KIND" CHECK ("OBJECT_KIND" IN ('table', 'field', 'structure', 'component', 'array-type', 'data-element', 'domain', 'fixed-value', 'class', 'interface', 'method', 'attribute', 'constant', 'include'))
);

-- create-table /RT/DOMAINS
CREATE TABLE "/RT/DOMAINS" (
  "DOMAIN_NAME" VARCHAR(63) NOT NULL,
  "PACKAGE_ID" VARCHAR(16),
  "DESCRIPTION" TEXT,
  "BASE_TYPE" VARCHAR(10) NOT NULL,
  "LENGTH" INTEGER,
  "DECIMALS" INTEGER,
  "DEFAULT_KIND" VARCHAR(5) NOT NULL,
  "DEFAULT_VALUE" TEXT,
  "ALLOW_EMPTY" BOOLEAN,
  CONSTRAINT "/RT/DOMAINS#PK" PRIMARY KEY ("DOMAIN_NAME"),
  CONSTRAINT "/RT/DOMAINS#FK#PACKAGE" FOREIGN KEY ("PACKAGE_ID") REFERENCES "/RT/PACKAGES" ("PACKAGE_ID") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/DOMAINS#CK#BASE_TYPE" CHECK ("BASE_TYPE" IN ('CHAR', 'STRING', 'INT4', 'INT8', 'DEC', 'DATE', 'TIMESTAMP', 'BOOL', 'UUID', 'BLOB')),
  CONSTRAINT "/RT/DOMAINS#CK#DEFAULT_KIND" CHECK ("DEFAULT_KIND" IN ('NONE', 'NULL', 'VALUE'))
);

-- create-table /RT/DATA_ELEMENTS
CREATE TABLE "/RT/DATA_ELEMENTS" (
  "DATA_ELEMENT" VARCHAR(63) NOT NULL,
  "PACKAGE_ID" VARCHAR(16) NOT NULL,
  "DOMAIN_NAME" VARCHAR(63) NOT NULL,
  CONSTRAINT "/RT/DATA_ELEMENTS#PK" PRIMARY KEY ("DATA_ELEMENT"),
  CONSTRAINT "/RT/DATA_ELEMENTS#FK#PACKAGE" FOREIGN KEY ("PACKAGE_ID") REFERENCES "/RT/PACKAGES" ("PACKAGE_ID") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/DATA_ELEMENTS#FK#DOMAIN" FOREIGN KEY ("DOMAIN_NAME") REFERENCES "/RT/DOMAINS" ("DOMAIN_NAME") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /RT/DATA_ELEMENT_TEXTS
CREATE TABLE "/RT/DATA_ELEMENT_TEXTS" (
  "DATA_ELEMENT" VARCHAR(63) NOT NULL,
  "LANGUAGE" VARCHAR(2) NOT NULL,
  "SHORT_LABEL" VARCHAR(10) NOT NULL,
  "MEDIUM_LABEL" VARCHAR(20) NOT NULL,
  "LONG_LABEL" VARCHAR(40) NOT NULL,
  "HEADING" VARCHAR(40) NOT NULL,
  "DESCRIPTION" TEXT,
  CONSTRAINT "/RT/DATA_ELEMENT_TEXTS#PK" PRIMARY KEY ("DATA_ELEMENT", "LANGUAGE"),
  CONSTRAINT "/RT/DATA_ELEMENT_TEXTS#FK#DATA_ELEMENT" FOREIGN KEY ("DATA_ELEMENT") REFERENCES "/RT/DATA_ELEMENTS" ("DATA_ELEMENT") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/DATA_ELEMENT_TEXTS#FK#LANGUAGE" FOREIGN KEY ("LANGUAGE") REFERENCES "/RT/LANGUAGES" ("LANGUAGE") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /RT/DOMAIN_VALUES
CREATE TABLE "/RT/DOMAIN_VALUES" (
  "DOMAIN_NAME" VARCHAR(63) NOT NULL,
  "POSITION" INTEGER NOT NULL,
  "VALUE" TEXT NOT NULL,
  "DESCRIPTION" TEXT,
  "VALUE_NAME" VARCHAR(63),
  CONSTRAINT "/RT/DOMAIN_VALUES#PK" PRIMARY KEY ("DOMAIN_NAME", "POSITION"),
  CONSTRAINT "/RT/DOMAIN_VALUES#FK#DOMAIN" FOREIGN KEY ("DOMAIN_NAME") REFERENCES "/RT/DOMAINS" ("DOMAIN_NAME") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /RT/TABLES
CREATE TABLE "/RT/TABLES" (
  "TABLE_NAME" VARCHAR(63) NOT NULL,
  "PACKAGE_ID" VARCHAR(16),
  "DESCRIPTION" TEXT,
  "TENANT_SPECIFIC" BOOLEAN NOT NULL,
  "DATA_CLASS" VARCHAR(20) NOT NULL,
  "PK_NAME" VARCHAR(63) NOT NULL,
  CONSTRAINT "/RT/TABLES#PK" PRIMARY KEY ("TABLE_NAME"),
  CONSTRAINT "/RT/TABLES#FK#PACKAGE" FOREIGN KEY ("PACKAGE_ID") REFERENCES "/RT/PACKAGES" ("PACKAGE_ID") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/TABLES#CK#DATA_CLASS" CHECK ("DATA_CLASS" IN ('configuration', 'application', 'runtimeConfiguration', 'system'))
);

-- create-table /RT/EXTENSIONS
CREATE TABLE "/RT/EXTENSIONS" (
  "PACKAGE_ID" VARCHAR(16) NOT NULL,
  "TABLE_NAME" VARCHAR(63) NOT NULL,
  "DESCRIPTION" TEXT,
  CONSTRAINT "/RT/EXTENSIONS#PK" PRIMARY KEY ("PACKAGE_ID", "TABLE_NAME"),
  CONSTRAINT "/RT/EXTENSIONS#FK#PACKAGE" FOREIGN KEY ("PACKAGE_ID") REFERENCES "/RT/PACKAGES" ("PACKAGE_ID") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/EXTENSIONS#FK#TABLE" FOREIGN KEY ("TABLE_NAME") REFERENCES "/RT/TABLES" ("TABLE_NAME") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /RT/FIELDS
CREATE TABLE "/RT/FIELDS" (
  "TABLE_NAME" VARCHAR(63) NOT NULL,
  "FIELD_NAME" VARCHAR(63) NOT NULL,
  "POSITION" INTEGER NOT NULL,
  "LOCAL_NAME" VARCHAR(63) NOT NULL,
  "DESCRIPTION" TEXT,
  "PACKAGE_ID" VARCHAR(16),
  "ORIGIN" VARCHAR(10) NOT NULL,
  "DOMAIN_NAME" VARCHAR(63) NOT NULL,
  "NOT_NULL" BOOLEAN NOT NULL,
  "DEFAULT_VALUE" TEXT,
  "KEY_POSITION" INTEGER,
  "DATA_ELEMENT" VARCHAR(63),
  "CHECK_NAME" VARCHAR(63) NOT NULL,
  "DEFAULT_KIND" VARCHAR(5) NOT NULL,
  "INCLUDE_NAME" VARCHAR(63),
  "SOURCE_NAME" VARCHAR(63),
  CONSTRAINT "/RT/FIELDS#PK" PRIMARY KEY ("TABLE_NAME", "FIELD_NAME"),
  CONSTRAINT "/RT/FIELDS#FK#TABLE" FOREIGN KEY ("TABLE_NAME") REFERENCES "/RT/TABLES" ("TABLE_NAME") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/FIELDS#FK#DOMAIN" FOREIGN KEY ("DOMAIN_NAME") REFERENCES "/RT/DOMAINS" ("DOMAIN_NAME") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/FIELDS#FK#PACKAGE" FOREIGN KEY ("PACKAGE_ID") REFERENCES "/RT/PACKAGES" ("PACKAGE_ID") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/FIELDS#FK#DATA_ELEMENT" FOREIGN KEY ("DATA_ELEMENT") REFERENCES "/RT/DATA_ELEMENTS" ("DATA_ELEMENT") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/FIELDS#CK#ORIGIN" CHECK ("ORIGIN" IN ('TABLE', 'EXTENSION', 'TENANT', 'INCLUDE')),
  CONSTRAINT "/RT/FIELDS#CK#DEFAULT_KIND" CHECK ("DEFAULT_KIND" IN ('NONE', 'NULL', 'VALUE'))
);

-- create-table /RT/FOREIGN_KEYS
CREATE TABLE "/RT/FOREIGN_KEYS" (
  "TABLE_NAME" VARCHAR(63) NOT NULL,
  "FK_NAME" VARCHAR(63) NOT NULL,
  "PACKAGE_ID" VARCHAR(16),
  "ORIGIN" VARCHAR(10) NOT NULL,
  "TARGET_TABLE" VARCHAR(63) NOT NULL,
  "CONSTRAINT_NAME" VARCHAR(63) NOT NULL,
  CONSTRAINT "/RT/FOREIGN_KEYS#PK" PRIMARY KEY ("TABLE_NAME", "FK_NAME"),
  CONSTRAINT "/RT/FOREIGN_KEYS#FK#TABLE" FOREIGN KEY ("TABLE_NAME") REFERENCES "/RT/TABLES" ("TABLE_NAME") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/FOREIGN_KEYS#FK#TARGET" FOREIGN KEY ("TARGET_TABLE") REFERENCES "/RT/TABLES" ("TABLE_NAME") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/FOREIGN_KEYS#FK#PACKAGE" FOREIGN KEY ("PACKAGE_ID") REFERENCES "/RT/PACKAGES" ("PACKAGE_ID") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/FOREIGN_KEYS#CK#ORIGIN" CHECK ("ORIGIN" IN ('TABLE', 'EXTENSION', 'TENANT', 'INCLUDE'))
);

-- create-table /RT/FK_FIELDS
CREATE TABLE "/RT/FK_FIELDS" (
  "TABLE_NAME" VARCHAR(63) NOT NULL,
  "FK_NAME" VARCHAR(63) NOT NULL,
  "POSITION" INTEGER NOT NULL,
  "FIELD_NAME" VARCHAR(63) NOT NULL,
  "TARGET_FIELD" VARCHAR(63) NOT NULL,
  CONSTRAINT "/RT/FK_FIELDS#PK" PRIMARY KEY ("TABLE_NAME", "FK_NAME", "POSITION"),
  CONSTRAINT "/RT/FK_FIELDS#FK#FOREIGN_KEY" FOREIGN KEY ("TABLE_NAME", "FK_NAME") REFERENCES "/RT/FOREIGN_KEYS" ("TABLE_NAME", "FK_NAME") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /RT/LOG
CREATE TABLE "/RT/LOG" (
  "LOG_ID" UUID NOT NULL,
  "OPERATION" VARCHAR(16) NOT NULL,
  "TARGET" VARCHAR(63),
  "STARTED_AT" TIMESTAMPTZ NOT NULL,
  "FINISHED_AT" TIMESTAMPTZ NOT NULL,
  "STATUS" VARCHAR(10) NOT NULL,
  "MESSAGE" TEXT,
  CONSTRAINT "/RT/LOG#PK" PRIMARY KEY ("LOG_ID"),
  CONSTRAINT "/RT/LOG#CK#OPERATION" CHECK ("OPERATION" IN ('MIGRATE', 'INSTALL', 'UPGRADE', 'UNINSTALL', 'TENANT_DELETE', 'LANGUAGE_REMOVE')),
  CONSTRAINT "/RT/LOG#CK#STATUS" CHECK ("STATUS" IN ('SUCCESS', 'FAILED'))
);

-- create-table /RT/LOG_PACKAGES
CREATE TABLE "/RT/LOG_PACKAGES" (
  "LOG_ID" UUID NOT NULL,
  "PACKAGE_ID" VARCHAR(16) NOT NULL,
  "VERSION_FROM" VARCHAR(64),
  "VERSION_TO" VARCHAR(64),
  CONSTRAINT "/RT/LOG_PACKAGES#PK" PRIMARY KEY ("LOG_ID", "PACKAGE_ID"),
  CONSTRAINT "/RT/LOG_PACKAGES#FK#LOG" FOREIGN KEY ("LOG_ID") REFERENCES "/RT/LOG" ("LOG_ID") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /RT/LOG_STATEMENTS
CREATE TABLE "/RT/LOG_STATEMENTS" (
  "LOG_ID" UUID NOT NULL,
  "POSITION" INTEGER NOT NULL,
  "STATEMENT" TEXT NOT NULL,
  "DESTRUCTIVE" BOOLEAN NOT NULL,
  CONSTRAINT "/RT/LOG_STATEMENTS#PK" PRIMARY KEY ("LOG_ID", "POSITION"),
  CONSTRAINT "/RT/LOG_STATEMENTS#FK#LOG" FOREIGN KEY ("LOG_ID") REFERENCES "/RT/LOG" ("LOG_ID") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /RT/MIGRATIONS
CREATE TABLE "/RT/MIGRATIONS" (
  "VERSION" INTEGER NOT NULL,
  "APPLIED_AT" TIMESTAMPTZ NOT NULL,
  CONSTRAINT "/RT/MIGRATIONS#PK" PRIMARY KEY ("VERSION")
);

-- create-table /RT/PACKAGE_DEPS
CREATE TABLE "/RT/PACKAGE_DEPS" (
  "PACKAGE_ID" VARCHAR(16) NOT NULL,
  "REQUIRED_ID" VARCHAR(16) NOT NULL,
  "VERSION_CONSTRAINT" TEXT,
  CONSTRAINT "/RT/PACKAGE_DEPS#PK" PRIMARY KEY ("PACKAGE_ID", "REQUIRED_ID"),
  CONSTRAINT "/RT/PACKAGE_DEPS#FK#PACKAGE" FOREIGN KEY ("PACKAGE_ID") REFERENCES "/RT/PACKAGES" ("PACKAGE_ID") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/PACKAGE_DEPS#FK#REQUIRED" FOREIGN KEY ("REQUIRED_ID") REFERENCES "/RT/PACKAGES" ("PACKAGE_ID") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /RT/SETTINGS
CREATE TABLE "/RT/SETTINGS" (
  "SETTING_ID" VARCHAR(63) NOT NULL,
  "PACKAGE_ID" VARCHAR(16) NOT NULL,
  "ROOT_TABLE" VARCHAR(63) NOT NULL,
  CONSTRAINT "/RT/SETTINGS#PK" PRIMARY KEY ("SETTING_ID"),
  CONSTRAINT "/RT/SETTINGS#FK#PACKAGE" FOREIGN KEY ("PACKAGE_ID") REFERENCES "/RT/PACKAGES" ("PACKAGE_ID") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/SETTINGS#FK#ROOT_TABLE" FOREIGN KEY ("ROOT_TABLE") REFERENCES "/RT/TABLES" ("TABLE_NAME") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /RT/SETTING_EXTENSIONS
CREATE TABLE "/RT/SETTING_EXTENSIONS" (
  "PACKAGE_ID" VARCHAR(16) NOT NULL,
  "SETTING_ID" VARCHAR(63) NOT NULL,
  CONSTRAINT "/RT/SETTING_EXTENSIONS#PK" PRIMARY KEY ("PACKAGE_ID", "SETTING_ID"),
  CONSTRAINT "/RT/SETTING_EXTENSIONS#FK#PACKAGE" FOREIGN KEY ("PACKAGE_ID") REFERENCES "/RT/PACKAGES" ("PACKAGE_ID") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/SETTING_EXTENSIONS#FK#SETTING" FOREIGN KEY ("SETTING_ID") REFERENCES "/RT/SETTINGS" ("SETTING_ID") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /RT/SETTING_TABLES
CREATE TABLE "/RT/SETTING_TABLES" (
  "TABLE_NAME" VARCHAR(63) NOT NULL,
  "SETTING_ID" VARCHAR(63) NOT NULL,
  "PACKAGE_ID" VARCHAR(16) NOT NULL,
  "POSITION" INTEGER NOT NULL,
  "PARENT_TABLE" VARCHAR(63),
  "FK_NAME" VARCHAR(63),
  "ALLOW_CREATE" BOOLEAN NOT NULL,
  "ALLOW_UPDATE" BOOLEAN NOT NULL,
  "ALLOW_DELETE" BOOLEAN NOT NULL,
  CONSTRAINT "/RT/SETTING_TABLES#PK" PRIMARY KEY ("TABLE_NAME"),
  CONSTRAINT "/RT/SETTING_TABLES#FK#SETTING" FOREIGN KEY ("SETTING_ID") REFERENCES "/RT/SETTINGS" ("SETTING_ID") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/SETTING_TABLES#FK#TABLE" FOREIGN KEY ("TABLE_NAME") REFERENCES "/RT/TABLES" ("TABLE_NAME") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/SETTING_TABLES#FK#PARENT" FOREIGN KEY ("PARENT_TABLE") REFERENCES "/RT/SETTING_TABLES" ("TABLE_NAME") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/SETTING_TABLES#FK#FOREIGN_KEY" FOREIGN KEY ("TABLE_NAME", "FK_NAME") REFERENCES "/RT/FOREIGN_KEYS" ("TABLE_NAME", "FK_NAME") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/SETTING_TABLES#FK#PACKAGE" FOREIGN KEY ("PACKAGE_ID") REFERENCES "/RT/PACKAGES" ("PACKAGE_ID") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /RT/SETTING_TEXTS
CREATE TABLE "/RT/SETTING_TEXTS" (
  "SETTING_ID" VARCHAR(63) NOT NULL,
  "LANGUAGE" VARCHAR(2) NOT NULL,
  "LABEL" VARCHAR(60) NOT NULL,
  "DESCRIPTION" TEXT,
  CONSTRAINT "/RT/SETTING_TEXTS#PK" PRIMARY KEY ("SETTING_ID", "LANGUAGE"),
  CONSTRAINT "/RT/SETTING_TEXTS#FK#SETTING" FOREIGN KEY ("SETTING_ID") REFERENCES "/RT/SETTINGS" ("SETTING_ID") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/SETTING_TEXTS#FK#LANGUAGE" FOREIGN KEY ("LANGUAGE") REFERENCES "/RT/LANGUAGES" ("LANGUAGE") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /RT/SOURCES
CREATE TABLE "/RT/SOURCES" (
  "PACKAGE_ID" VARCHAR(16) NOT NULL,
  "FILE_PATH" VARCHAR(255) NOT NULL,
  "OBJECT_NAME" VARCHAR(63) NOT NULL,
  "KIND" VARCHAR(9) NOT NULL,
  "TEXT" TEXT NOT NULL,
  "SHA256" VARCHAR(64) NOT NULL,
  CONSTRAINT "/RT/SOURCES#PK" PRIMARY KEY ("PACKAGE_ID", "FILE_PATH"),
  CONSTRAINT "/RT/SOURCES#FK#PACKAGE" FOREIGN KEY ("PACKAGE_ID") REFERENCES "/RT/PACKAGES" ("PACKAGE_ID") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/SOURCES#CK#KIND" CHECK ("KIND" IN ('class', 'interface', 'include'))
);

-- create-table /RT/STRUCTURES
CREATE TABLE "/RT/STRUCTURES" (
  "STRUCTURE_NAME" VARCHAR(63) NOT NULL,
  "PACKAGE_ID" VARCHAR(16) NOT NULL,
  CONSTRAINT "/RT/STRUCTURES#PK" PRIMARY KEY ("STRUCTURE_NAME"),
  CONSTRAINT "/RT/STRUCTURES#FK#PACKAGE" FOREIGN KEY ("PACKAGE_ID") REFERENCES "/RT/PACKAGES" ("PACKAGE_ID") DEFERRABLE INITIALLY IMMEDIATE
);

-- create-table /RT/STRUCTURE_ELEMENTS
CREATE TABLE "/RT/STRUCTURE_ELEMENTS" (
  "STRUCTURE_NAME" VARCHAR(63) NOT NULL,
  "POSITION" INTEGER NOT NULL,
  "ELEMENT_KIND" VARCHAR(9) NOT NULL,
  "COMPONENT_NAME" VARCHAR(63),
  "PACKAGE_ID" VARCHAR(16) NOT NULL,
  "ORIGIN" VARCHAR(9),
  "TYPE_KIND" VARCHAR(12),
  "TYPE_NAME" VARCHAR(63),
  "INCLUDE_NAME" VARCHAR(63),
  "NOT_NULL" BOOLEAN NOT NULL,
  "DEFAULT_KIND" VARCHAR(5) NOT NULL,
  "DEFAULT_VALUE" TEXT,
  "DESCRIPTION" TEXT,
  CONSTRAINT "/RT/STRUCTURE_ELEMENTS#PK" PRIMARY KEY ("STRUCTURE_NAME", "POSITION"),
  CONSTRAINT "/RT/STRUCTURE_ELEMENTS#FK#STRUCTURE" FOREIGN KEY ("STRUCTURE_NAME") REFERENCES "/RT/STRUCTURES" ("STRUCTURE_NAME") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/STRUCTURE_ELEMENTS#FK#PACKAGE" FOREIGN KEY ("PACKAGE_ID") REFERENCES "/RT/PACKAGES" ("PACKAGE_ID") DEFERRABLE INITIALLY IMMEDIATE,
  CONSTRAINT "/RT/STRUCTURE_ELEMENTS#CK#ELEMENT_KIND" CHECK ("ELEMENT_KIND" IN ('COMPONENT', 'INCLUDE')),
  CONSTRAINT "/RT/STRUCTURE_ELEMENTS#CK#ORIGIN" CHECK ("ORIGIN" IN ('STRUCTURE', 'EXTENSION')),
  CONSTRAINT "/RT/STRUCTURE_ELEMENTS#CK#TYPE_KIND" CHECK ("TYPE_KIND" IN ('DATA_ELEMENT', 'DOMAIN', 'STRUCTURE', 'ARRAY_TYPE')),
  CONSTRAINT "/RT/STRUCTURE_ELEMENTS#CK#DEFAULT_KIND" CHECK ("DEFAULT_KIND" IN ('NONE', 'NULL', 'VALUE'))
);

