  CONSTRAINT "/RT/STRUCTURE_EXTENSIONS#FK#STRUCTURE" FOREIGN KEY ("STRUCTURE_NAME") REFERENCES "/RT/STRUCTURES" ("STRUCTURE_NAME") DEFERRABLE INITIALLY IMMEDIATE
);

